mapper.select:
/* selectPersonalIdNum - Lee JiSeob */
SELECT ISRY_APP.SA_FN_GET_RENU_NO('PN', #{userId}, '') FROM DUAL
/* SELECT CHR(TO_NUMBER(TO_CHAR(SYSDATE, 'RRRR')) - 1956) || LPAD(TO_CHAR(SYSDATE, 'DDD'), 3, '0') || LPAD(TO_CHAR(SYSTIMESTAMP, 'FF'), 6, '0') AS UNIQ_NO FROM DUAL */

/* getWorkerId - Lee JiSeob */
SELECT ISRY_APP.SA_FN_GET_RENU_NO('EN', #{userId}, '') FROM DUAL
/* SELECT SCA100_SQ01.NEXTVAL FROM DUAL */

/* selectOrgRegion - Lee JiSeob */
SELECT
DISTINCT
D.CTPV_NM, D.ENG_CTPV_NM, D.SGG_CD, D.SGG_NM
FROM SAA000 C /* 기관코드 */, SAA020 D /* 시군구코드 */
WHERE C.RGN_CD = D.SGG_CD AND C.APRV_YN = 'Y' AND (C.DEL_YN IS NULL OR C.DEL_YN = 'N')
AND C.UNT_TASKWK_SE_CD = #{UNIT_SYSTEM}
AND C.UNT_TASKWK_SE_CD = #{UNIT_TASKWORK}
AND C.INST_NO IN ( SELECT E.INST_NO FROM SAA000 E /* 기관코드 */ START WITH E.INST_NO != #{UP_INST_NO} AND E.UP_INST_NO = #{UP_INST_NO} CONNECT BY PRIOR E.INST_NO = E.UP_INST_NO )
ORDER BY D.SGG_CD

/* selectSiGunGu - Lee JiSeob */
SELECT SGG_CD, CTPV_SE_CD, CTPV_NM, SGG_NM, ENG_CTPV_NM, ENG_SGG_NM, SRTNG_SQNCE, DEL_YN, FRST_RGTR_ID, FRST_REG_DT, LAST_MDFR_ID, LAST_MDFCN_DT
FROM SAA020 /* 시군구코드 */
AND ENG_CTPV_NM = #{SIDO}
AND ( SGG_NM LIKE '%' || #{SEARCH} || '%' OR CTPV_NM LIKE '%' || #{SEARCH} || '%' OR ENG_CTPV_NM LIKE '%' || #{SEARCH} || '%' OR ENG_SGG_NM LIKE '%' || #{SEARCH} || '%' )


        /* selectCiCount - Lee JiSeob */

		SELECT
			COUNT(*) AS CNT

		FROM SCA300 /* 개인정보 */

		WHERE NVL(DEL_YN, 'N') = 'N'

		AND (

		  MOPH_ME_CERT_DN_VALUE_CN = #{CI}

		  OR 

		  SNS_SIMPC_CERT_DN_VALUE_CN = #{CI}

		)


        /* selectCiCount2 - Lee JiSeob */

		SELECT
			COUNT(*) AS CNT

		FROM SCA300 C /* 개인정보 */

		WHERE MOPH_ME_CERT_DN_VALUE_CN = #{CI}

		AND NVL(DEL_YN, 'N') = 'N'


        /* selectCiSimpleCount - Lee JiSeob */

        SELECT
            COUNT(*) AS CNT

        FROM SCA300 /* 개인정보 */

        WHERE NVL(DEL_YN, 'N') = 'N'

        AND
        (
	        SNS_SIMPC_CERT_DN_VALUE_CN = #{CI}

	        OR

	        MOPH_ME_CERT_DN_VALUE_CN = #{CI}
        )


/* selectCiSimpleCount2 - Lee JiSeob */

SELECT
    COUNT(*) AS CNT

FROM SCA300 C /* 개인정보 */

WHERE SNS_SIMPC_CERT_DN_VALUE_CN = #{CI}

AND NVL(DEL_YN, 'N') = 'N'


/* selectCertificateCount - Lee JiSeob */

SELECT
    COUNT(*) AS CNT

FROM SCA300 /* 개인정보 */

WHERE OFCERT_ME_CERT_DN_VALUE_CN = #{signerDN}

AND NVL(DEL_YN, 'N') = 'N'
